        return str(len(a)) + '\n' + ' '.join(map(str, a)) + '\n' + str(len(qs)) + '\n' + ' '.join(map(str, qs))
    tests = [fmt([5], [5, 4]), fmt([-10**9, 10**9], [-10**9, 10**9, 0]), fmt([1, 2, 3], [0, 1, 2, 3, 4])]
