        tests.append(fmt(a, qs))
    def big(n, q, present):
        a = sorted(set(rng.sample(range(-10**9 + 1, 10**9), n - 2)) | {-10**9, 10**9})
        qs = [rng.choice(a) if rng.random() < present else rng.randint(-10**9, 10**9) for _ in range(q)]
        return fmt(a, qs)
    tests.append(big(2000, 2000, 0.5))
    tests.append(big(100000, 100000, 0.5))
    tests.append(big(100000, 100000, 1.0))
    a = list(range(-50000, 50000))
    tests.append(fmt(a, [rng.choice([a[-1], a[-2], a[0], a[50000]]) for _ in range(100000)]))
